const {chromium}=require('playwright'),fs=require('fs');(async()=>{fs.mkdirSync('campaign-build',{recursive:true});const b=await chromium.launch({executablePath:'/usr/bin/google-chrome'});let p=await b.newPage();await p.goto('https://www.arquindex.com.br/',{waitUntil:'networkidle'});const brand=await p.evaluate(()=>({font:getComputedStyle(document.body).fontFamily,color:getComputedStyle(document.querySelector('h1')||document.body).color,accent:document.querySelector('meta[name="theme-color"]')?.content||'#0f766e',logo:document.querySelector('img[src*="arquindex-logo-oficial"]')?.src}));fs.writeFileSync('campaign-build/brand.json',JSON.stringify(brand));for(const x of require('../social/20261028/campaign.json')){let page=await b.newPage({viewport:{width:1080,height:1080}});await page.setContent('<html><body style="margin:0;background:#f4f8f8;font-family:'+brand.font.replaceAll('"',"'")+';color:'+brand.color+'"><div style="height:1080px;box-sizing:border-box;padding:72px;border-top:24px solid '+brand.accent+'"><img src="'+brand.logo+'" style="max-width:330px;max-height:100px"><p style="margin-top:70px;letter-spacing:4px;font-size:24px;color:'+brand.accent+'">CONTEÚDO TÉCNICO • ARQUINDEX</p><h1 style="font-size:66px;line-height:1.08;max-width:880px">'+x.title+'</h1><p style="font-size:31px;line-height:1.6">'+x.steps.slice(0,3).map((s,i)=>String(i+1).padStart(2,'0')+' — '+s).join('<br>')+'</p><div style="margin-top:42px;border-radius:20px;background:'+brand.accent+';padding:24px;color:white;font-size:30px">BH e região metropolitana<br>Consulte escopo e logística de atendimento</div><p style="font-size:23px">Leia o roteiro técnico na página indicada na publicação.</p></div></body></html>');await page.waitForTimeout(1200);await page.screenshot({path:'campaign-build/'+x.i+'.jpg',type:'jpeg',quality:94});await page.close();}await b.close();})();